html:
{%- import "altor_project/templates/print/altor_print.html" as ap with context -%}
{%- set c = altor_company(doc.company, doc) -%}
{{ ap.styles(c) }}
{%- set p = altor_party(doc) -%}
{%- set vat = altor_item_taxes(doc) -%}
{%- set is_return = doc.get("is_return") -%}
<div class="ap">
{{ ap.header(c, "TAX CREDIT NOTE" if is_return else "TAX INVOICE", "إشعار دائن ضريبي" if is_return else "فاتورة ضريبية", [
    ["Invoice No.", doc.name],
    ["Invoice Date", ap.date(doc.posting_date)],
    ["Due Date", ap.date(doc.due_date) if not is_return else None],
    ["Against Invoice", doc.get("return_against") if is_return else None],
    ["LPO / PO No.", doc.get("po_no")],
    ["LPO Date", ap.date(doc.get("po_date"))]
]) }}
{{ ap.two_boxes(ap.party_box("Bill To", p), ap.info_box("Project & Reference", [
    ["Project", doc.get("project")],
    ["Location", doc.get("custom_location")],
    ["Client", doc.get("custom_client")],
    ["Contract Ref.", doc.get("custom_contract_reference")],
    ["Contract Date", ap.date(doc.get("custom_contract_date"))],
    ["Quotation", doc.get("custom_quotation")],
    ["Place of Supply", doc.get("vat_emirate") or doc.get("place_of_supply")]
])) }}
<table class="items">
  <thead><tr>
    <th style="width:5%">#<span class="ar">رقم</span></th>
    <th>Description<span class="ar">البيان</span></th>
    <th style="width:7%">Unit<span class="ar">الوحدة</span></th>
    <th class="right" style="width:7%">Qty<span class="ar">الكمية</span></th>
    <th class="right" style="width:11%">Rate<span class="ar">سعر الوحدة</span></th>
    <th class="right" style="width:12%">Taxable Amount<span class="ar">المبلغ الخاضع</span></th>
    <th class="right" style="width:7%">VAT %<span class="ar">النسبة</span></th>
    <th class="right" style="width:10%">VAT Amount<span class="ar">مبلغ الضريبة</span></th>
    <th class="right" style="width:12%">Total ({{ doc.currency }})<span class="ar">الإجمالي</span></th>
  </tr></thead>
  <tbody>
  {%- for item in doc.get("items") %}{% set t = vat[item.name] %}
  <tr><td>{{ loop.index }}</td><td><div class="item-name">{{ item.item_name }}</div>{% if item.description and item.description | striptags | trim != item.item_name %}{{ ap.bullets(item.description) }}{% endif %}</td>
    <td>{{ item.uom }}</td><td class="right">{{ ap.num(item.qty) }}</td><td class="right">{{ ap.amt(item.rate) }}</td>
    <td class="right">{{ ap.amt(t.net) }}</td><td class="right">{{ t.rate }}%</td><td class="right">{{ ap.amt(t.amount) }}</td><td class="right"><b>{{ ap.amt(t.total) }}</b></td></tr>
  {%- endfor %}
  </tbody>
</table>
{%- set paid = (doc.get("rounded_total") or doc.get("grand_total") or 0) - (doc.get("outstanding_amount") or 0) %}
{{ ap.totals(doc, True, [
    ["Advance / Paid", ap.money(paid, doc) if doc.docstatus == 1 and paid > 0.005 and not is_return else None],
    ["Balance Due", ap.money(doc.get("outstanding_amount"), doc) if doc.docstatus == 1 and paid > 0.005 and not is_return else None]
]) }}
{%- if doc.get("custom_item_detail") %}
<div class="sec"><div class="sec-title">Details</div><table class="items"><tbody>
{%- for r in doc.custom_item_detail %}<tr><td>{{ r.get("description") or r.get("details") or r.get("item") or "" }}</td></tr>{% endfor %}
</tbody></table></div>
{%- endif %}
{{ ap.section("Payment Terms", ap.payment_terms(doc)) }}
{{ ap.section("Terms & Conditions", doc.get("terms")) }}
{{ ap.bank(c) }}
{{ ap.signatures(c, ["Authorised Signatory", "Received by (Name, Signature & Stamp)"]) }}
{{ ap.footer(c) }}
</div>
